AND DIVISION = ${DIVISION}

mapper.select:

SELECT 
	COUNT(*) AS CODE_CHECK,
	SMS_CODE
FROM CBCI_SMS_TEMPLATE
WHERE SMS_CODE = #{SMS_CODE}
AND SMS_KEY = #{SMS_KEY}


SELECT
	SMS_CONTENT
FROM CBCI_SMS_TEMPLATE
WHERE SMS_CODE = #{SMS_CODE}
AND SMS_KEY = #{SMS_KEY}
